  brush.fill("#a3a3a3", 60); // grey
  brush.fill("#c8c8c8", 40); // light grey
  brush.fill("#d3d3d3", 10); // lighter grey
  brush.fill("#8f8f8f", 10); // light grey

  // Horizon
  brush.fill("#3c2300", 100); // dark green
