function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();
  fill("#e08a72", 200); // sky
  brush.fillTexture(0.2, 0.1); // soft, airy texture
  brush.beginShape();
  brush.vertex(0, 0); // top left
  brush.vertex(300, 0); // top right
  brush.vertex(200, 200); // hill center
  brush.vertex(0, 300); // bottom left
  brush.vertex(300, 300); // bottom right
  brush.endShape(true);

  // ground
  fill("#012014", 180); // dark green
  brush.fillTexture(0.8, 0.1); // chunky, soft texture
  brush.beginShape();
  brush.vertex(0, 300);
  brush.vertex(400, 300);
  brush.vertex(200, 400);
  brush.vertex(0, 400);
  brush.vertex(400, 400);
  brush.endShape(true);

  // hills and grass
  brush.fillTexture(0.3, 0.5); // wild
  brush.noStroke();
  brush.beginShape();
  brush.vertex(0, 250);
  brush.vertex(100, 210);
  brush.vertex(200, 100); // hill 1
  brush.vertex(0, 300);   // hill 2
  brush.vertex(400, 300); // hill 3
  brush.endShape(true);

  // tree on the hill
  fill("#3c3c3c", 20); // dark green
  brush.fillTexture(0.6, 0); // solid
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(180, 90);
  brush.vertex(120, 80);
  brush.vertex(100, 80); // small shape
  brush.endShape(true);

  // sunset colors on top
  fill("#a15a24", 255); // warm
  brush.fillTexture(1.0, 0.1); // muted
  brush.beginShape();
  brush.vertex(0, 180);
  brush.vertex(300, 180);
  brush.vertex(200, 240);
  brush.vertex(0, 280);
  brush.vertex(300, 280);

