function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();
  fill("#eb6f95"); // golden
  circle(200, 160, 100); // sun

  // Hills
  fill("#9c875c"); // green
  brush.beginShape();
  brush.normal(0.002); // slight up from bottom to make them look up
  brush.vertex(0, 160, 0); // bottom left
  brush.vertex(200, 180, 0); // middle
  brush.vertex(400, 160, 0); // bottom right
  brush.endShape();

  // Ground
  fill("#3f3f3f"); // dark green
  brush.beginShape();
  brush.normal(0.002); // slight up
  brush.vertex(0, 160, 0); // bottom left
  brush.vertex(200, 160, 0); // middle
  brush.vertex(400, 160, 0); // bottom right
  brush.endShape();

  // Hills with grass
  fill("#446844"); // darker green
  brush.beginShape();
  brush.normal(0.002);
  brush.vertex(0, 160, 0);
  brush.vertex(200, 180, 0);
  brush.vertex(400, 160, 0);
  brush.endShape();

  // Stormy sky
  fill("#5c2c2d"); // dark grey
  brush.beginShape();
  brush.normal(-0.005); // down slightly
  brush.vertex(0, 120, 0);
  brush.vertex(400, 100, 0);
  brush.vertex(0, 140, 0);
  brush.vertex(400, 120, 0);
  brush.endShape();

  // Gulls
  brush.fill("#d49145"); // blue
  brush.beginShape();
  brush.normal(0.002);
  brush.vertex(-10, 120, 0);
  brush.vertex(-10, 140, 0);
  brush.vertex(-30, 120, 0); // further left
  brush.endShape();
}
