function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();

  // Sky
  brush.fill("#80c3ff", 0.3);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(0, height);
  brush.vertex(width, 0);
  brush.vertex(width, height);
  brush.endShape(true);

  // Hills
  brush.fill("#a8d4b9", 0.5);
  brush.beginShape();
  for (let x = -150; x < 200; x += 100) {
    brush.vertex(x, 0);
    brush.vertex(x, height * 0.85);
  }
  brush.endShape(true);
  brush.pushMatrix();
  brush.translate(0, 0);
  brush.rotateY(PI / 4);
  brush.pushMatrix();
  brush.translate(-100, 0);
  brush.fill("#66835f", 0.5);
  brush.beginShape();
  for (let x = -200; x < 300; x += 100) {
    brush.vertex(x, 0);
    brush.vertex(x, height * 0.85);
  }
  brush.endShape(true);
  brush.popMatrix();

  // Clouds
  brush.fill("#d3d3d3", 0.3);
  brush.beginShape();
