  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();
  fillTexture(0, 1); // sky
  fillTexture(0.85, 0.6); // orange
  fillTexture(0.5, 0.8); // red
  fillTexture(0.1, 0.1); // dark red

  // Paint hills
  brush.fill("#99b599", 100); // light green
  brush.fill("#81a384", 100); // green
  brush.fill("#729971", 100); // darker green
  brush.fill("#3b6534", 100); // dark green

  // Sun
  brush.fill("#e08a72", 150); // warm yellow
  brush.fill("#f8b230", 200); // golden light

  // Paint top hill
  brush.fill("#99b599", 100);
  brush.beginShape();
  brush.vertex(0, -50);
  brush.vertex(200, -100);
  brush.vertex(400, 0);
  brush.endShape();
  brush.stroke("#99b599");
}

function fillTexture(ratio, opacity) {
  const dark = "#3b6534"; // dark green
  const light = "#99b599"; // light green
  const ground = "#6b6b6b"; // grayish soil
  const neutral = "#f4efe4";

  // From the top to bottom: sky, light green, dark green, ground, neutral
  const colors = [neutral, "#99b599", "#81a384", "#729971", "#3b6534"];

  let pos = 0;
  if (ratio < 1) {
    brush.fill(colors[pos], opacity);
    pos++;
  } else {
    brush.fill(colors[pos], opacity);
    pos++;
  }
}
